import Combine
import XCTest

extension XCTestCase {
    func awaitOutput<P: Publisher>(
        _ publisher: P,
        timeout: TimeInterval = 1,
        file: StaticString = #filePath,
        line: UInt = #line
    ) throws -> P.Output {
        var result: Result<P.Output, P.Failure>?
        let exp = expectation(description: "publisher output")
        let cancellable = publisher.first().sink(
            receiveCompletion: { if case let .failure(e) = $0 { result = .failure(e) }; exp.fulfill() },
            receiveValue: { result = .success($0) }
        )
        wait(for: [exp], timeout: timeout)
        cancellable.cancel()
        let unwrapped = try XCTUnwrap(result, "publisher produced no output", file: file, line: line)
        return try unwrapped.get()
    }
}

import Foundation

public func withRetry<T>(
    attempts: Int = 3,
    baseDelay: Duration = .milliseconds(200),
    _ operation: () async throws -> T
) async throws -> T {
    precondition(attempts > 0)
    var lastError: Error?
    for attempt in 0..<attempts {
        do {
            return try await operation()
        } catch {
            lastError = error
            if attempt < attempts - 1 {
                try await Task.sleep(for: baseDelay * (1 << attempt))
            }
        }
    }
    throw lastError!
}

import Foundation

final class MockURLProtocol: URLProtocol {
    nonisolated(unsafe) static var responses: [String: (status: Int, body: Data)] = [:]

    override class func canInit(with request: URLRequest) -> Bool { true }
    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }

    override func startLoading() {
        let key = request.url?.absoluteString ?? ""
        let (status, body) = Self.responses[key] ?? (404, Data())
        let response = HTTPURLResponse(url: request.url!, statusCode: status, httpVersion: nil, headerFields: nil)!
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: body)
        client?.urlProtocolDidFinishLoading(self)
    }

    override func stopLoading() {}
}

extension URLSession {
    static var mocked: URLSession {
        let config = URLSessionConfiguration.ephemeral
        config.protocolClasses = [MockURLProtocol.self]
        return URLSession(configuration: config)
    }
}

